67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
76	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
77	     * stored lower-cased.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
81	
82	    /** A well-formed postcode: exactly four digits. */
83	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
84	
85	    /**
86	     * Email domains belonging to disposable-address providers. An owner whose email domain (the part
87	     * after the '@', compared case-insensitively) is one of these is rejected: such addresses are
88	     * throwaway and unsuitable for a durable owner record.
89	     */
90	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /**
94	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
95	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
96	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
97	     */
98	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
99	        "NSW", new int[] {2000, 2099},
100	        "VIC", new int[] {3000, 3099},
101	        "QLD", new int[] {4000, 4099});
102	
103	    /** Dedicated audit logger; one line is emitted per successful owner create. */
104	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
105	
106	    /**
107	     * The maximum number of owners a single city may contain. Once a city already holds this many
108	     * owners, any further create naming that city is rejected as a conflict.
109	     */
110	    private static final int MAX_OWNERS_PER_CITY = 50;
111	
112	    /**
113	     * The maximum number of owners that may be registered in a single day. Once this many owners
114	     * already carry today's registration date, any further create is rejected as too many requests.
115	     */
116	    private static final int MAX_OWNERS_PER_DAY = 100;
117	
118	    /**
119	     * The number of owners that must already be registered on today's business day before a response
120	     * carries a bulk-signup warning. Once more than this many owners already carry today's
121	     * registration date, responses set {@code bulkSignupWarning} true.
122	     */
123	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
124	
125	    /**
126	     * The fixed list of public holidays. A registration date that lands on one of these dates is
127	     * rolled forward to the next non-holiday business day, just as a weekend date is.
128	     */
129	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
130	        LocalDate.of(2026, 1, 1),
131	        LocalDate.of(2026, 1, 26),
132	        LocalDate.of(2026, 4, 25),
133	        LocalDate.of(2026, 12, 25),
134	        LocalDate.of(2026, 12, 28));
135	
136	    private final ClinicService clinicService;
137	
138	    private final OwnerMapper ownerMapper;
139	
140	    private final PetMapper petMapper;
141	
142	    private final VisitMapper visitMapper;
143	
144	    public OwnerRestControllerV1(ClinicService clinicService,
145	                                 OwnerMapper ownerMapper,
146	                                 PetMapper petMapper,
147	                                 VisitMapper visitMapper) {
148	        this.clinicService = clinicService;
149	        this.ownerMapper = ownerMapper;
150	        this.petMapper = petMapper;
151	        this.visitMapper = visitMapper;
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
157	        Collection<Owner> owners;
158	        if (lastName != null) {
159	            owners = this.clinicService.findOwnerByLastName(lastName);
160	        } else {
161	            owners = this.clinicService.findAllOwners();
162	        }
163	        if (owners.isEmpty()) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
167	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        OwnerDto ownerDto = toOwnerDto(owner);
178	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
179	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
185	        String idempotencyKey = currentIdempotencyKey();
186	        if (idempotencyKey != null) {
187	            Owner alreadyCreated = findOwnerByIdempotencyKey(idempotencyKey);
188	            if (alreadyCreated != null) {
189	                OwnerDto existingDto = toOwnerDto(alreadyCreated);
190	                existingDto.setBulkSignupWarning(isBulkSignupWarningActive());
191	                return new ResponseEntity<>(existingDto, HttpStatus.OK);
192	            }
193	        }
194	        validateRequiredOwnerFields(ownerFieldsDto);
195	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
196	        LocalDate suppliedOrDefaultDate =
197	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
198	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
199	        rejectDailyLimitExceeded(registrationDate);
200	        rejectCityAtCapacity(ownerFieldsDto.getCity());
201	        HttpHeaders headers = new HttpHeaders();
202	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
203	        validatePostcode(owner.getCity(), owner.getPostcode());
204	        applyAddress(owner);
205	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
206	        owner.setTelephone(normalizedTelephone);
207	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
208	        owner.setEmail(normalizeEmail(owner.getEmail()));
209	        rejectDuplicateIdentity(owner);
210	        applyPossibleDuplicate(owner, declaredHouseholdMember);
211	        owner.setRegistrationDate(registrationDate);
212	        owner.setCustomerCode(
213	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
214	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
215	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
216	        owner.setIdempotencyKey(idempotencyKey);
217	        applyMembershipLevelCeiling(owner);
218	        this.clinicService.saveOwner(owner);
219	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
220	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
221	            owner.getMembershipNumber());
222	        OwnerDto ownerDto = toOwnerDto(owner);
223	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
224	        headers.setLocation(UriComponentsBuilder.newInstance()
225	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
226	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
227	    }
228	
229	    /**
230	     * The idempotency key supplied on the current create request, read from its {@code Idempotency-Key}
231	     * header. A blank value is treated as absent.
232	     *
233	     * @return the trimmed {@code Idempotency-Key} header, or {@code null} when it is absent or blank
234	     */
235	    private String currentIdempotencyKey() {
236	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
237	            String header = attributes.getRequest().getHeader("Idempotency-Key");
238	            if (header != null && !header.isBlank()) {
239	                return header.trim();
240	            }
241	        }
242	        return null;
243	    }
244	
245	    /**
246	     * Finds the owner originally created under the given idempotency key, so a repeated create carrying
247	     * an already-seen key returns that owner instead of creating a duplicate. The lowest-id match is
248	     * returned when more than one owner somehow carries the key.
249	     *
250	     * @param idempotencyKey the create request's idempotency key
251	     * @return the owner first created under the key, or {@code null} when the key has not been seen
252	     */
253	    private Owner findOwnerByIdempotencyKey(String idempotencyKey) {
254	        return this.clinicService.findAllOwners().stream()
255	            .filter(existing -> idempotencyKey.equals(existing.getIdempotencyKey()))
256	            .min(java.util.Comparator.comparing(Owner::getId))
257	            .orElse(null);
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
263	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
264	        if (currentOwner == null) {
265	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	        }
267	        currentOwner.setAddress(ownerFieldsDto.getAddress());
268	        currentOwner.setCity(ownerFieldsDto.getCity());
269	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
270	        currentOwner.setLastName(ownerFieldsDto.getLastName());
271	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
272	        this.clinicService.saveOwner(currentOwner);
273	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Transactional
278	    @Override
279	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
280	        Owner owner = this.clinicService.findOwnerById(ownerId);
281	        if (owner == null) {
282	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	        }
284	        owner.setDeleted(true);
285	        this.clinicService.saveOwner(owner);
286	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner == null) {
294	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	        }
296	        HttpHeaders headers = new HttpHeaders();
297	        Pet pet = petMapper.toPet(petFieldsDto);
298	        owner.setId(ownerId);
299	        pet.setOwner(owner);
300	        pet.getType().setName(null);
301	        this.clinicService.savePet(pet);
302	        PetDto petDto = petMapper.toPetDto(pet);
303	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
304	            .buildAndExpand(pet.getId()).toUri());
305	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
311	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
312	        if (currentOwner != null) {
313	            Pet currentPet = this.clinicService.findPetById(petId);
314	            if (currentPet != null) {
315	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
316	                currentPet.setName(petFieldsDto.getName());
317	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
318	                this.clinicService.savePet(currentPet);
319	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
320	            }
321	        }
322	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
328	        HttpHeaders headers = new HttpHeaders();
329	        Visit visit = visitMapper.toVisit(visitFieldsDto);
330	        Pet pet = new Pet();
331	        pet.setId(petId);
332	        visit.setPet(pet);
333	        this.clinicService.saveVisit(visit);
334	        VisitDto visitDto = visitMapper.toVisitDto(visit);
335	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
336	            .buildAndExpand(visit.getId()).toUri());
337	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
338	    }
339	
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
344	        Owner owner = this.clinicService.findOwnerById(ownerId);
345	        if (owner != null) {
346	            Pet pet = owner.getPet(petId);
347	            if (pet != null) {
348	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
349	            }
350	        }
351	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	    }
353	
354	    /**
355	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
356	     * offending field is collected so the caller learns exactly which values must be supplied.
357	     *
358	     * @param ownerFieldsDto the submitted owner payload
359	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
360	     *         telephone is missing or blank
361	     */
362	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
363	        List<String> missingFields = new ArrayList<>();
364	        if (isBlank(ownerFieldsDto.getFirstName())) {
365	            missingFields.add("firstName");
366	        }
367	        if (isBlank(ownerFieldsDto.getLastName())) {
368	            missingFields.add("lastName");
369	        }
370	        if (isBlank(ownerFieldsDto.getAddressLine1())
371	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
372	            missingFields.add("address");
373	        }
374	        if (isBlank(ownerFieldsDto.getCity())) {
375	            missingFields.add("city");
376	        }
377	        if (isBlank(ownerFieldsDto.getTelephone())) {
378	            missingFields.add("telephone");
379	        }
380	        if (!missingFields.isEmpty()) {
381	            throw new MissingOwnerFieldsException(missingFields);
382	        }
383	    }
384	
385	    private boolean isBlank(String value) {
386	        return value == null || value.isBlank();
387	    }
388	
389	    /**
390	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
391	     * current date. A registration date may not lie in the future; a value equal to today or in the
392	     * past is accepted, and an absent date is left to default to the server date.
393	     *
394	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
395	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
396	     */
397	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
398	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
399	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
400	        }
401	    }
402	
403	    /**
404	     * Counts the existing owners who, before this create, already share the given first and last name.
405	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
406	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
407	     * case or spacing still count as the same name.
408	     *
409	     * @param firstName the first name of the owner being created
410	     * @param lastName the last name of the owner being created
411	     * @return the number of existing owners sharing both names (zero when none)
412	     */
413	    private int countNamesakes(String firstName, String lastName) {
414	        String first = normalizeHouseholdField(firstName);
415	        String last = normalizeHouseholdField(lastName);
416	        return (int) this.clinicService.findAllOwners().stream()
417	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
418	                && normalizeHouseholdField(existing.getLastName()).equals(last))
419	            .count();
420	    }
421	
