452	    /**
453	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
454	     * forward, and a date that lands on a listed public holiday is likewise rolled forward, until the
455	     * result is a weekday that is not a public holiday; a weekday that is not a holiday is returned
456	     * unchanged. This applies whether the date was supplied on the request or defaulted to the
457	     * server's current date.
458	     *
459	     * @param date the effective registration date (supplied or defaulted)
460	     * @return the first non-holiday weekday on or after the supplied date
461	     */
462	    /**
463	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
464	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
465	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
466	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
467	     *
468	     * @return {@code true} when more than the threshold number of owners are already registered on
469	     *         today's business day, otherwise {@code false}
470	     */
471	    private boolean isBulkSignupWarningActive() {
472	        LocalDate today = toBusinessDay(LocalDate.now());
473	        long ownersToday = this.clinicService.findAllOwners().stream()
474	            .filter(existing -> today.equals(existing.getRegistrationDate()))
475	            .count();
476	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
477	    }
