479	    private LocalDate toBusinessDay(LocalDate date) {
480	        LocalDate adjusted = switch (date.getDayOfWeek()) {
481	            case SATURDAY -> date.plusDays(2);
482	            case SUNDAY -> date.plusDays(1);
483	            default -> date;
484	        };
485	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
486	            adjusted = adjusted.plusDays(1);
487	        }
488	        return adjusted;
489	    }
490	
491	    private boolean isWeekend(LocalDate date) {
492	        return switch (date.getDayOfWeek()) {
493	            case SATURDAY, SUNDAY -> true;
494	            default -> false;
495	        };
496	    }
