508	    /**
509	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
510	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
511	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
512	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
513	     * to the same base code only when they share a region and produce the same telephone-and-last-name
514	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
515	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
516	     *
517	     * @param postcode the owner's postcode, used first to derive the region
518	     * @param city the owner's city, used to derive the region when the postcode maps to none
519	     * @param normalizedTelephone the owner's normalized (E.164) telephone
520	     * @param lastName the owner's last name
521	     * @return the formatted, de-duplicated customer code
522	     */
523	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
524	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
525	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
526	        String baseCode = region + "-" + hash8;
527	        return deduplicateCustomerCode(baseCode);
528	    }
