530	    /**
531	     * De-duplicates a computed customer code against every existing owner's customer code. When no
532	     * existing owner already carries the base code it is returned unchanged; otherwise '-&lt;n&gt;' is
533	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner holds.
534	     *
535	     * @param baseCode the computed, formatted customer code before de-duplication
536	     * @return the base code when unique, otherwise the base code suffixed with '-&lt;n&gt;'
537	     */
538	    private String deduplicateCustomerCode(String baseCode) {
539	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
540	            .map(Owner::getCustomerCode)
541	            .filter(java.util.Objects::nonNull)
542	            .collect(java.util.stream.Collectors.toSet());
543	        if (!existingCodes.contains(baseCode)) {
544	            return baseCode;
545	        }
546	        int n = 2;
547	        while (existingCodes.contains(baseCode + "-" + n)) {
548	            n++;
549	        }
550	        return baseCode + "-" + n;
551	    }
