568	    /**
569	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
570	     * country calling code. Australia ('+61') uses 9 national digits and the North American
571	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
572	     * E.164 length (8 to 15 digits overall).
573	     */
574	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
575	        java.util.Map.of("61", 9, "1", 10);
576	
577	    /**
578	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
579	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
580	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
581	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
582	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
583	     * E.164 string is what gets stored and returned.
584	     *
585	     * @param telephone the raw telephone value from the request
586	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
587	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
588	     *         national number has the wrong length for its country code
589	     */
590	    private String normalizeTelephone(String telephone) {
591	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
592	        String e164;
593	        if (cleaned.startsWith("+")) {
594	            e164 = cleaned;
595	        } else {
596	            String national = cleaned;
597	            if (national.startsWith("0")) {
598	                national = national.substring(1);
599	            }
600	            e164 = "+61" + national;
601	        }
602	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
603	            throw new InvalidOwnerFieldsException(List.of("telephone"));
604	        }
605	        validateNationalNumberLength(e164);
606	        return e164;
607	    }
608	
609	    /**
610	     * Rejects an E.164 telephone whose national number does not have the exact length its country
611	     * calling code requires. The digits after the leading '+' are split into the longest matching
612	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
613	     * code is known and the national number's length differs from the required count the telephone is
614	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
615	     *
616	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
617	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
618	     */
619	    private void validateNationalNumberLength(String e164) {
620	        String digits = e164.substring(1);
621	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
622	            String countryCode = digits.substring(0, codeLength);
623	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
624	            if (requiredNationalLength != null) {
625	                int nationalLength = digits.length() - codeLength;
626	                if (nationalLength != requiredNationalLength) {
627	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
628	                }
629	                return;
630	            }
631	        }
632	    }
