634	    /**
635	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
636	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
637	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
638	     * stored and returned is the value lower-cased.
639	     *
640	     * @param email the raw email value from the request, or {@code null} when none was supplied
641	     * @return the lower-cased email, or {@code null} when no email was supplied
642	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
643	     *         its domain is on the disposable-domain blocklist
644	     */
645	    private String normalizeEmail(String email) {
646	        if (email == null || email.isBlank()) {
647	            return null;
648	        }
649	        if (!EMAIL_PATTERN.matcher(email).matches()) {
650	            throw new InvalidOwnerFieldsException(List.of("email"));
651	        }
652	        String normalized = email.toLowerCase(Locale.ROOT);
653	        String domain = normalized.substring(normalized.indexOf('@') + 1);
654	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
655	            throw new InvalidOwnerFieldsException(List.of("email"));
656	        }
657	        return normalized;
658	    }
