660	    /**
661	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
662	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
663	     * When present it must be exactly four digits and, when the owner's city maps to a known region
664	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
665	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
666	     * region accepts any four-digit postcode.
667	     *
668	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
669	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
670	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
671	     *         for the city's region
672	     */
673	    private void validatePostcode(String city, String postcode) {
674	        if (postcode == null || postcode.isBlank()) {
675	            return;
676	        }
677	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
678	            throw new InvalidOwnerFieldsException(List.of("postcode"));
679	        }
680	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
681	        if (range == null) {
682	            return;
683	        }
684	        int value = Integer.parseInt(postcode);
685	        if (value < range[0] || value > range[1]) {
686	            throw new InvalidOwnerFieldsException(List.of("postcode"));
687	        }
688	    }
