690	    /**
691	     * Resolves an owner's address from the supplied structured and flat fields, preferring the
692	     * structured form. Whichever address fields were supplied are normalized (see
693	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
694	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (an
695	     * absent or blank {@code addressLine2} is cleared) and the composed {@code address} is the
696	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
697	     * appended when the latter is present. When no {@code addressLine1} is supplied the flat
698	     * {@code address} is used unchanged for backward compatibility and the structured lines are
699	     * cleared. The composed {@code address} is what every later step reads.
700	     *
701	     * @param owner the owner being created, mapped from the request but not yet normalized
702	     */
703	    private void applyAddress(Owner owner) {
704	        String line1 = normalizeAddress(owner.getAddressLine1());
705	        String line2 = normalizeAddress(owner.getAddressLine2());
706	        String flat = normalizeAddress(owner.getAddress());
707	        if (!line1.isEmpty()) {
708	            owner.setAddressLine1(line1);
709	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
710	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
711	        } else {
712	            owner.setAddressLine1(null);
713	            owner.setAddressLine2(null);
714	            owner.setAddress(flat);
715	        }
716	    }
