718	    /**
719	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
720	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
721	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
722	     * normalized form is what gets stored, returned and used for every address comparison (the
723	     * required-field check, household duplicate detection and the shared household id).
724	     *
725	     * @param address the raw address value from the request, or {@code null}
726	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
727	     */
728	    private String normalizeAddress(String address) {
729	        if (address == null) {
730	            return "";
731	        }
732	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
733	        if (collapsed.isEmpty()) {
734	            return "";
735	        }
736	        String[] tokens = collapsed.split(" ");
737	        for (int i = 0; i < tokens.length; i++) {
738	            switch (tokens[i]) {
739	                case "ST" -> tokens[i] = "STREET";
740	                case "RD" -> tokens[i] = "ROAD";
741	                case "AVE" -> tokens[i] = "AVENUE";
742	                default -> { }
743	            }
744	        }
745	        return String.join(" ", tokens);
746	    }
