748	    /**
749	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
750	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
751	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
752	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
753	     * so two members of one household with different telephones have different keys and are both
754	     * allowed; only an owner whose entire key is identical is a duplicate.
755	     *
756	     * @param owner the owner being created, with its telephone, email and householdId already resolved
757	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
758	     */
759	    private void rejectDuplicateIdentity(Owner owner) {
760	        String identityKey = owner.getIdentityKey();
761	        boolean inUse = this.clinicService.findAllOwners().stream()
762	            .filter(existing -> !existing.isDeleted())
763	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
764	        if (inUse) {
765	            throw new DuplicateOwnerIdentityException(identityKey);
766	        }
767	    }
