769	    /**
770	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
771	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
772	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
773	     * (its identity key differs) and is still created. When at least one soft match exists,
774	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
775	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
776	     * <p>
777	     * A declared household member - an owner that acknowledged sharing an existing household via
778	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
779	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
780	     *
781	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
782	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
783	     */
784	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
785	        if (declaredHouseholdMember) {
786	            owner.setPossibleDuplicate(false);
787	            return;
788	        }
789	        String lastName = normalizeHouseholdField(owner.getLastName());
790	        String postcode = owner.getPostcode();
791	        String telephone = owner.getTelephone();
792	        Owner match = null;
793	        if (postcode != null && !postcode.isBlank()) {
794	            match = this.clinicService.findAllOwners().stream()
795	                .filter(existing -> !existing.isDeleted())
796	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
797	                .filter(existing -> postcode.equals(existing.getPostcode()))
798	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
799	                .min(java.util.Comparator.comparing(Owner::getId))
800	                .orElse(null);
801	        }
802	        if (match != null) {
803	            owner.setPossibleDuplicate(true);
804	            owner.setPossibleDuplicateOf(match.getId());
805	        } else {
806	            owner.setPossibleDuplicate(false);
807	        }
808	    }
