876	    /**
877	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
878	     * last name and a postcode: the {@code householdId} is derived deterministically from the
879	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
880	     * owners with the same last name and postcode always resolve to the same identifier and belong to
881	     * the same household automatically - no acknowledgement is needed to create the link.
882	     * <p>
883	     * When the owner supplies a postcode its {@code householdId} is always assigned; an owner with no
884	     * postcode belongs to no household and is left without an identifier. Joining an existing household
885	     * is not itself a conflict: hard duplicate detection is handled solely by the identity key (see
886	     * {@link #rejectDuplicateIdentity(Owner)}), so two members of one household with different
887	     * telephones are both created. An owner that explicitly acknowledges an existing household via
888	     * {@code sharesHousehold} is reported as a declared member so it is not flagged as a possible
889	     * duplicate.
890	     *
891	     * @param owner the owner being created
892	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
893	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
894	     *         {@code false}
895	     */
896	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
897	        String postcode = owner.getPostcode();
898	        if (postcode == null || postcode.isBlank()) {
899	            return false;
900	        }
901	        String lastName = normalizeHouseholdField(owner.getLastName());
902	        String householdId = generateHouseholdId(lastName, postcode);
903	        owner.setHouseholdId(householdId);
904	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
905	            .filter(existing -> !existing.isDeleted())
906	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
907	        return hasExistingMember && Boolean.TRUE.equals(sharesHousehold);
908	    }
