910	    /**
911	     * Builds the stable identifier shared by the members of one household. It is derived purely from
912	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
913	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
914	     * two fields joined by a single '|'.
915	     *
916	     * @param normalizedLastName the household's last name, already normalized for comparison
917	     * @param postcode the household's postcode
918	     * @return the shared household identifier
919	     */
920	    private String generateHouseholdId(String normalizedLastName, String postcode) {
921	        String key = normalizedLastName + '|' + postcode;
922	        try {
923	            byte[] digest = MessageDigest.getInstance("SHA-256")
924	                .digest(key.getBytes(StandardCharsets.UTF_8));
925	            StringBuilder hex = new StringBuilder();
926	            for (byte b : digest) {
927	                hex.append(String.format("%02X", b));
928	                if (hex.length() >= 12) {
929	                    break;
930	                }
931	            }
932	            return hex.substring(0, 12);
933	        } catch (NoSuchAlgorithmException e) {
934	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
935	        }
936	    }
937	
938	    /**
939	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
940	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
941	     * the owner's normalized telephone and last name.
942	     *
943	     * @param input the string to digest
944	     * @param length the number of leading upper-case hex characters to return
945	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
946	     */
947	    private String sha256UpperHex(String input, int length) {
948	        try {
949	            byte[] digest = MessageDigest.getInstance("SHA-256")
950	                .digest(input.getBytes(StandardCharsets.UTF_8));
951	            StringBuilder hex = new StringBuilder();
952	            for (byte b : digest) {
953	                hex.append(String.format("%02X", b));
954	                if (hex.length() >= length) {
955	                    break;
956	                }
957	            }
958	            return hex.substring(0, length);
959	        } catch (NoSuchAlgorithmException e) {
960	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
961	        }
962	    }
963	
964	    /**
965	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
966	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
967	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
968	     * expands common abbreviations.
969	     *
970	     * @param value the raw last name, or {@code null}
971	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
972	     */
973	    private String normalizeHouseholdField(String value) {
974	        if (value == null) {
975	            return "";
976	        }
977	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
978	    }
979	}
