97	    private Integer membershipLevelCeiling;
98	
99	    /**
100	     * The number of owners belonging to this owner's household (owners sharing the same
101	     * {@code householdId}), including this owner. It is a derived, non-persistent value populated
102	     * when an owner is mapped for a response.
103	     */
104	    @Transient
105	    private Integer householdMemberCount;
