107	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
108	    private Set<Pet> pets;
109	
110	    public String getAddress() {
111	        return this.address;
112	    }
113	
114	    public void setAddress(String address) {
115	        this.address = address;
116	    }
117	
118	    public String getAddressLine1() {
119	        return this.addressLine1;
120	    }
121	
122	    public void setAddressLine1(String addressLine1) {
123	        this.addressLine1 = addressLine1;
124	    }
