126	    public String getAddressLine2() {
127	        return this.addressLine2;
128	    }
129	
130	    public void setAddressLine2(String addressLine2) {
131	        this.addressLine2 = addressLine2;
132	    }
133	
134	    public String getCity() {
135	        return this.city;
136	    }
137	
138	    public void setCity(String city) {
139	        this.city = city;
140	    }
141	
142	    public String getTelephone() {
143	        return this.telephone;
144	    }
145	
146	    public void setTelephone(String telephone) {
147	        this.telephone = telephone;
148	    }
149	
150	    /**
151	     * The known E.164 country calling codes this owner's telephone may carry, used only to split the
152	     * stored number into its country code and national digits for display. Australia ('+61') and the
153	     * North American Numbering Plan ('+1') mirror the codes the create endpoint recognises.
154	     */
155	    private static final String[] KNOWN_COUNTRY_CODES = {"61", "1"};
156	
157	    /**
158	     * The stored E.164 {@code telephone} formatted for human reading: the country calling code (kept
159	     * with its leading {@code '+'}), a space, then the national digits grouped in threes from the left
160	     * and separated by spaces (e.g. {@code +61412345678} becomes {@code "+61 412 345 678"}). The
161	     * country code is taken as the longest {@link #KNOWN_COUNTRY_CODES} match, defaulting to a
162	     * two-digit code when none is recognised. It is a derived value; the raw {@code telephone} stays in
163	     * E.164 form.
164	     *
165	     * @return the human-formatted telephone, or the raw {@code telephone} when it is {@code null} or
166	     *         not in E.164 form
167	     */
168	    public String getTelephoneDisplay() {
169	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
170	            return this.telephone;
171	        }
172	        String digits = this.telephone.substring(1);
173	        String countryCode = null;
174	        for (String code : KNOWN_COUNTRY_CODES) {
175	            if (digits.startsWith(code) && digits.length() > code.length()
176	                && (countryCode == null || code.length() > countryCode.length())) {
177	                countryCode = code;
178	            }
179	        }
180	        if (countryCode == null) {
181	            countryCode = digits.substring(0, Math.min(2, digits.length()));
182	        }
183	        String national = digits.substring(countryCode.length());
184	        StringBuilder sb = new StringBuilder("+").append(countryCode);
185	        for (int i = 0; i < national.length(); i += 3) {
186	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
187	        }
188	        return sb.toString();
189	    }
