370	    /**
371	     * The owner's membership points, a non-negative score. It starts at 0 and accumulates: 2 points
372	     * when an email address is present, 1 point when the owner has no namesakes ({@code namesakeCount}
373	     * is zero), 2 points for a household of 3 or more members ({@code householdMemberCount} is at least
374	     * 3), and 3 points for tenure &mdash; the number of elapsed fiscal years (the fiscal year starts on
375	     * 1 July) from {@code registrationDate} to today &mdash; of more than 1.
376	     *
377	     * @return the derived membership points (0 or more)
378	     */
379	    public Integer getMembershipPoints() {
380	        int points = 0;
381	        if (this.email != null && !this.email.isBlank()) {
382	            points += 2;
383	        }
384	        if (this.namesakeCount != null && this.namesakeCount == 0) {
385	            points += 1;
386	        }
387	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
388	            points += 2;
389	        }
390	        if (this.registrationDate != null
391	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) > 1) {
