399	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
400	     * points. The result is then capped at the owner's {@link #getMembershipLevelCeiling() membership
401	     * level ceiling} when one is set, so a new owner never exceeds one above the highest level among the
402	     * other members of its household at the time it was created.
403	     *
404	     * @return the derived membership level (1 to 4), capped at the membership-level ceiling when set
405	     */
406	    public Integer getMembershipLevel() {
407	        int points = getMembershipPoints();
408	        int level;
409	        if (points >= 6) {
410	            level = 4;
411	        } else if (points >= 4) {
412	            level = 3;
413	        } else if (points >= 2) {
414	            level = 2;
415	        } else {
416	            level = 1;
417	        }
418	        if (this.membershipLevelCeiling != null && level > this.membershipLevelCeiling) {
419	            return this.membershipLevelCeiling;
