424	    /**
425	     * The Luhn check digit (0-9) computed over the digits contained in this owner's
426	     * {@code customerCode}. Non-digit characters are ignored; the rightmost digit is doubled.
427	     *
428	     * @return the single Luhn check digit, or {@code null} when there is no customer code
429	     */
430	    public Integer getCheckDigit() {
431	        if (this.customerCode == null) {
432	            return null;
433	        }
434	        int sum = 0;
435	        boolean dbl = true;
436	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
437	            char c = this.customerCode.charAt(i);
438	            if (c < '0' || c > '9') {
439	                continue;
440	            }
441	            int d = c - '0';
442	            if (dbl) {
443	                d *= 2;
444	                if (d > 9) {
445	                    d -= 9;
446	                }
447	            }
448	            sum += d;
449	            dbl = !dbl;
450	        }
451	        return (10 - (sum % 10)) % 10;
452	    }
